lemma MagmaHom.cancel_right {G H I : Type*} [Magma G] [Magma H] [Magma I] {f : G →◇ H}
    (hf : Function.Surjective f) (f₁ f₂ : H →◇ I) :
    f.comp f₁ = f.comp f₂ ↔ f₁ = f₂

